}elseif($type==='discount'){
    select('family','Type',['length'=>'Long stay','early'=>'Early booking','last'=>'Last minute','code'=>'Discount code','promo'=>'Date promotion'],$item['family']);
    input('min_nights','Minimum nights',$item['min_nights'],'number',true,'min="1" max="365"');input('max_nights','Maximum nights',$item['max_nights'],'number',false,'min="1" max="365"');
    select('kind','Amount type',['percent'=>'Percentage','fixed'=>'Fixed THB'],$item['kind']);input('display_value','Percentage or THB',number_format($item['value']/100,2,'.',''),'text',true,'inputmode="decimal"');
    input('code','Discount code',$item['code']);input('min_advance_days','Minimum days in advance',$item['min_advance_days'],'number',false,'min="0"');input('max_advance_days','Maximum days in advance',$item['max_advance_days'],'number',false,'min="0"');
    input('start_date','Stay from',$item['start_date'],'date');input('end_date','Stay until (exclusive)',$item['end_date'],'date');
}else{
    select('kind','Type',['fixed'=>'Fixed THB','percent'=>'Percentage'],$item['kind']);input('amount_thb','Fixed amount (THB)',number_format($item['amount_satang']/100,2,'.',''),'text',true,'inputmode="decimal"');input('percent','Percentage',number_format($item['percent_bps']/100,2,'.',''),'text',true,'inputmode="decimal"');
    select('basis','Percentage applies to',['nights_after_discount'=>'Nights after discounts','subtotal_plus_fees'=>'Nights after discounts + fixed fees'],$item['basis']);checkbox('per_night','Per night',(bool)$item['per_night']);checkbox('per_extra_guest','Per extra guest',(bool)$item['per_extra_guest']);
}
if($type!=='fee')input('priority','Priority',$item['priority'],'number',true,'min="-1000" max="1000"');?><button>Save rule</button></form></details><?php endforeach;?></section><?php endforeach;?>
